CREATE TABLE workspaces (
    id uuid NOT NULL,
    name text NOT NULL CONSTRAINT workspaces_name_check CHECK (char_length(name) BETWEEN 1 AND 200),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (id)
);
CREATE TABLE workspace_memberships (
    workspace_id uuid NOT NULL REFERENCES workspaces (id),
    actor_id uuid NOT NULL,
    role text NOT NULL CONSTRAINT workspace_memberships_role_check CHECK (role IN ('member', 'viewer')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor_id)
);
CREATE INDEX workspace_memberships_actor_idx ON workspace_memberships (actor_id);
